import csv
from collections import defaultdict
with open(CATALOG_CSV) as f:
    rows=list(csv.DictReader(f))
data=defaultdict(list)
with open(VALUES_CSV) as f:
    rd=csv.reader(f)
    next(rd)
    for row in rd:
        data[row[0]].append((row[1],float(row[2])))

def stat(ts):
    vts=sorted(data[ts])
    early=[v for ts_,v in vts if ts_ < "2018-07"]
    late=[v for ts_,v in vts if ts_ >= "2018-07"]
    return (sum(early)/len(early), sum(late)/len(late))

zones={}
for r in rows:
    if r["point_class"]=="Zone_Air_Temperature_Sensor":
        zones[r["point_uri"].split("#")[-1]]=r["timeseries_id"]
for k,v in sorted(zones.items()):
    if v in data:
        e,l=stat(v)
        print(k, round(e,2), round(l,2), "delta=", round(l-e,2))

# Power in Zone_F3_Z01 — check whether there's a series
print()
for r in rows:
    if "Zone_F3_Z01_Electric_Power" in r["point_uri"]:
        print("power ts:", r["timeseries_id"], "present?" , r["timeseries_id"] in data)
    if "Electric" in r["point_uri"] and "Zone" in r["point_uri"]:
        print(r["point_uri"].split("#")[-1], r["timeseries_id"] in data)
